import React, { createContext, useContext, useState } from 'react';
import { useAuth } from './AuthContext';
import { PERMISSIONS_MATRIX } from '../lib/permissionsMatrix';

const SearchContext = createContext(null);

// Menu items untuk search - includes all menus and submenus
const MENU_ITEMS = [
  // Dashboard
  { id: 'dashboard', label: 'Dasbor', path: '/', type: 'menu', menuId: 'dashboard' },
  
  // Users Menu
  { id: 'users-menu', label: 'Pengguna', path: '/users', type: 'menu', menuId: 'users-list' },
  { id: 'users-list', label: 'Daftar Pengguna', path: '/users', type: 'submenu', menuId: 'users-list' },
  { id: 'user-permissions', label: 'Hak Akses Pengguna', path: '/user-permissions', type: 'submenu', menuId: 'user-permissions' },
  { id: 'management-roles', label: 'Manajemen Role', path: '/roles', type: 'submenu', menuId: 'management-roles' },
  
  // Kepengurusan Menu
  { id: 'kepengurusan', label: 'Kepengurusan', path: '/management', type: 'menu', menuId: 'kepengurusan' },
  { id: 'pengurus', label: 'Pengurus', path: '/management', type: 'submenu', menuId: 'kepengurusan' },
  { id: 'rekening', label: 'Rekening Penerima', path: '/rekening', type: 'submenu', menuId: 'kepengurusan' },
  { id: 'surat', label: 'Surat', path: '/surat', type: 'submenu', menuId: 'kepengurusan' },
  
  // Residents Menu
  { id: 'residents', label: 'Penghuni', path: '/warga', type: 'menu', menuId: 'warga' },
  { id: 'warga', label: 'Warga', path: '/warga', type: 'submenu', menuId: 'warga' },
  { id: 'rumah', label: 'Rumah', path: '/rumah', type: 'submenu', menuId: 'warga' },
  
  // Karyawan
  { id: 'karyawan', label: 'Karyawan', path: '/karyawan', type: 'menu', menuId: 'karyawan' },
  
  // Finance Menu
  { id: 'finance', label: 'Keuangan', path: '/finance', type: 'menu', menuId: 'keuangan' },
  { id: 'kas', label: 'Kas', path: '/finance', type: 'submenu', menuId: 'keuangan' },
  { id: 'biaya-rutin', label: 'Biaya Rutin', path: '/biaya/rutin', type: 'submenu', menuId: 'finance' },
  { id: 'ipl', label: 'Iuran IPL', path: '/ipl', type: 'submenu', menuId: 'ipl' },
  { id: 'kasbon', label: 'Kasbon', path: '/kasbon', type: 'submenu', menuId: 'kasbon' },
  { id: 'laporan', label: 'Laporan', path: '/laporan', type: 'submenu', menuId: 'laporan' },
  
  // WhatsApp
  { id: 'whatsapp', label: 'Integrasi WhatsApp', path: '/whatsapp', type: 'menu', menuId: 'whatsapp' },
  
  // Log Aktivitas
  { id: 'aktivitas-log', label: 'Log Aktivitas', path: '/aktivitas-log', type: 'menu', menuId: 'aktivitas-log' },
  
  // Configuration Menu
  { id: 'configuration', label: 'Konfigurasi', path: '/biaya/kategori', type: 'menu', menuId: 'configuration' },
  { id: 'kategori-biaya', label: 'Kategori Biaya', path: '/biaya/kategori', type: 'submenu', menuId: 'configuration' },
  { id: 'tarif-ipl', label: 'Tarif IPL', path: '/tarif-ipl', type: 'submenu', menuId: 'configuration' },
  
  // Data Management
  { id: 'data-management', label: 'Kelola Data', path: '/data-management', type: 'menu', menuId: 'data-management' },
];

export const SearchProvider = ({ children }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [isSearching, setIsSearching] = useState(false);
  const { user } = useAuth();

  // Check if user has permission to access a menu
  const hasMenuPermission = (menuId) => {
    if (!user || !user.role) return false;
    
    // Admin memiliki akses ke semua menu
    if (user.role === 'admin') return true;
    
    // Check permission matrix untuk non-admin
    const rolePermissions = PERMISSIONS_MATRIX[user.role] || {};
    const menuPermission = rolePermissions[menuId];
    
    // Return true jika menu ada di permission matrix dan read permission true
    return menuPermission && menuPermission.read === true;
  };

  const performSearch = (query) => {
    setSearchQuery(query);
    setIsSearching(true);

    // Simulate search with timeout
    setTimeout(() => {
      if (query.trim()) {
        // Filter menu items by query dan check permissions
        const results = MENU_ITEMS.filter(item => {
          // Check if menu matches search query
          const matchesQuery = item.label.toLowerCase().includes(query.toLowerCase()) ||
            item.id.toLowerCase().includes(query.toLowerCase());
          
          // Check if user has permission to access this menu
          const hasPermission = hasMenuPermission(item.menuId);
          
          return matchesQuery && hasPermission;
        });
        setSearchResults(results.length > 0 ? results : []);
      } else {
        setSearchResults([]);
      }
      setIsSearching(false);
    }, 300);
  };

  const clearSearch = () => {
    setSearchQuery('');
    setSearchResults([]);
    setIsSearching(false);
  };

  return (
    <SearchContext.Provider value={{ 
      searchQuery, 
      searchResults, 
      isSearching, 
      performSearch, 
      clearSearch 
    }}>
      {children}
    </SearchContext.Provider>
  );
};

export const useSearch = () => {
  const context = useContext(SearchContext);
  if (!context) {
    throw new Error('useSearch must be used within SearchProvider');
  }
  return context;
};