import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { useAuth } from '@/contexts/AuthContext';
import { API_ENDPOINTS } from '@/config/api';
import { format } from 'date-fns';
import { id } from 'date-fns/locale';

export default function FundHistoryDialog({ open, onClose, fund }) {
    const { token } = useAuth();
    const [history, setHistory] = useState([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (open && fund) {
            loadHistory();
        }
    }, [open, fund]);

    const loadHistory = async () => {
        setLoading(true);
        try {
            // Fetch ALL history for now (backend handles sorting desc)
            const res = await fetch(API_ENDPOINTS.BUDGET_FUND_HISTORY(fund.id), {
                headers: { Authorization: `Bearer ${token}` }
            });
            if (res.ok) {
                const data = await res.json();
                setHistory(data);
            }
        } catch (err) {
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    const formatRp = (val) => `Rp ${Number(val).toLocaleString('id-ID')}`;

    return (
        <Dialog open={open} onOpenChange={onClose}>
            <DialogContent className="max-w-3xl max-h-[80vh] overflow-hidden flex flex-col">
                <DialogHeader>
                    <DialogTitle>Riwayat Transaksi: {fund?.nama}</DialogTitle>
                </DialogHeader>

                <div className="flex-1 overflow-auto mt-4 border rounded-md">
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>Tanggal</TableHead>
                                <TableHead>Tipe</TableHead>
                                <TableHead>Keterangan</TableHead>
                                <TableHead className="text-right">Jumlah</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {loading ? (
                                <TableRow>
                                    <TableCell colSpan={4} className="text-center py-8 text-gray-500">Memuat data...</TableCell>
                                </TableRow>
                            ) : history.length === 0 ? (
                                <TableRow>
                                    <TableCell colSpan={4} className="text-center py-8 text-gray-500">Belum ada transaksi</TableCell>
                                </TableRow>
                            ) : (
                                history.map((item) => (
                                    <TableRow key={item.id}>
                                        <TableCell className="whitespace-nowrap">
                                            {format(new Date(item.tanggal), 'dd MMM yyyy HH:mm', { locale: id })}
                                        </TableCell>
                                        <TableCell>
                                            <Badge variant={item.tipe === 'pemasukan' ? 'default' : 'destructive'}
                                                className={item.tipe === 'pemasukan' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}>
                                                {item.tipe === 'pemasukan' ? 'Masuk' : 'Keluar'}
                                            </Badge>
                                        </TableCell>
                                        <TableCell className="max-w-[200px]" title={item.deskripsi}>
                                            {item.deskripsi || '-'}
                                            {item.deskripsi === 'Auto alokasi Dana dari IPL' && (
                                                <Badge variant="outline" className="ml-2 bg-blue-50 text-blue-700 border-blue-200 text-[10px] py-0 px-1">
                                                    AUTO (IPL)
                                                </Badge>
                                            )}
                                        </TableCell>
                                        <TableCell className={`text-right font-medium ${item.tipe === 'pemasukan' ? 'text-green-600' : 'text-red-600'}`}>
                                            {item.tipe === 'pemasukan' ? '+' : '-'} {formatRp(item.amount)}
                                        </TableCell>
                                    </TableRow>
                                ))
                            )}
                        </TableBody>
                    </Table>
                </div>
            </DialogContent>
        </Dialog>
    );
}
