import { useState } from "react";
import { API_BASE_URL } from "@/config/api";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow
} from "@/components/ui/table";

import {
  AlertDialog,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogContent,
  AlertDialogCancel,
  AlertDialogAction
} from "@/components/ui/alert-dialog";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

import { toast } from "@/components/ui/sonner";
import { CheckCircle2, XCircle, MoreVertical, Edit, Key, Send, Trash2 } from "lucide-react";
import { useAuth } from "@/contexts/AuthContext";
import { useRolePermissions } from "@/hooks/useRolePermissions";

export default function UserTable({
  data,
  onEdit,
  onDelete,
  onSetPassword,
  onResetPassword,
  selectedRows,
  setSelectedRows
}) {
  const [sortField, setSortField] = useState("");
  const [sortDir, setSortDir] = useState("asc");
  const [deleteTarget, setDeleteTarget] = useState(null);
  const { token, user } = useAuth(); // 🔐 JWT + ROLE
  const { canRead, canUpdate, canDelete: canDeletePerm } = useRolePermissions(user?.role, token);

  const toggleSort = (field) => {
    const newDir =
      sortField === field && sortDir === "asc" ? "desc" : "asc";
    setSortField(field);
    setSortDir(newDir);
  };

  const sortedData = [...data].sort((a, b) => {
    if (!sortField) return 0;
    const aVal = a[sortField] ?? "";
    const bVal = b[sortField] ?? "";
    return sortDir === "asc"
      ? aVal.toString().localeCompare(bVal.toString())
      : bVal.toString().localeCompare(aVal.toString());
  });



  const toggleRow = (id) => {
    setSelectedRows(
      selectedRows.includes(id)
        ? selectedRows.filter((r) => r !== id)
        : [...selectedRows, id]
    );
  };

  const toggleAll = () => {
    if (selectedRows.length === data.length) setSelectedRows([]);
    else setSelectedRows(data.map((u) => u.id));
  };

  const formatDate = (val) => {
    if (!val) return "-";
    return new Date(val).toLocaleString("id-ID");
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    
    try {
      const res = await fetch(`${API_BASE_URL}/api/users/${deleteTarget.id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.detail || "Gagal menghapus user");
      }

      toast.success("User berhasil dihapus");
      setDeleteTarget(null);
      onDelete();
    } catch (err) {
      toast.error(err.message || "Gagal menghapus user");
    }
  };

  return (
    <>
    <Table className="border rounded-lg bg-white dark:bg-gray-900 shadow-sm">

      <TableHeader>
        <TableRow>

          {/* CHECKBOX */}
          <TableHead className="w-10">
            <input
              type="checkbox"
              checked={
                data.length > 0 && selectedRows.length === data.length
              }
              onChange={toggleAll}
            />
          </TableHead>

          <TableHead
            onClick={() => toggleSort("fullname")}
            className="cursor-pointer"
          >
            Nama {sortField === "fullname" && (sortDir === "asc" ? "▲" : "▼")}
          </TableHead>

          <TableHead
            onClick={() => toggleSort("username")}
            className="cursor-pointer"
          >
            Email {sortField === "username" && (sortDir === "asc" ? "▲" : "▼")}
          </TableHead>

          <TableHead>Kode Negara</TableHead>
          <TableHead>Nomor WhatsApp</TableHead>

          <TableHead
            onClick={() => toggleSort("created_at")}
            className="cursor-pointer"
          >
            Terakhir Login
          </TableHead>

          <TableHead>Blok / No.Rumah</TableHead>
          <TableHead>Status Warga</TableHead>
          <TableHead className="text-center">Status Aktif</TableHead>
          {canRead('users-list') && (canUpdate('users-list') || canDeletePerm('users-list')) && (<TableHead className="text-right">Aksi</TableHead>)}
        </TableRow>
      </TableHeader>

      <TableBody>
        {sortedData.map((u) => (
          <TableRow key={u.id}>

            {/* CHECKBOX */}
            <TableCell className="w-10">
              <input
                type="checkbox"
                checked={selectedRows.includes(u.id)}
                onChange={() => toggleRow(u.id)}
              />
            </TableCell>

            {/* NAMA */}
            <TableCell className="font-medium">{u.fullname}</TableCell>

            {/* EMAIL */}
            <TableCell>{u.username || "-"}</TableCell>

            {/* KODE NEGARA */}
           <TableCell>{u.country_code || "+62"}</TableCell>

            {/* NOMOR WA */}
            <TableCell>{u.whatsapp || "-"}</TableCell>

            {/* TERAKHIR LOGIN */}
           <TableCell>{formatDate(u.last_login)}</TableCell>

            {/* BLOK / RUMAH */}
            <TableCell>{u.block_house || "-"}</TableCell>

            {/* STATUS WARGA */}
            <TableCell>{u.role || "-"}</TableCell>

            {/* STATUS AKTIF */}
            <TableCell className="text-center">
              {u.status === "active" ? (
                <CheckCircle2 className="w-5 h-5 text-green-500 mx-auto" />
              ): (
                <XCircle className="w-5 h-5 text-red-500 mx-auto" />)}
            </TableCell>

            {/* AKSI */}
            <TableCell className="text-center">
              <DropdownMenu>
               {canRead('users-list') && canUpdate('users-list') && (
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                    <MoreVertical className="h-4 w-4" />
                  </Button>
                </DropdownMenuTrigger> )}
                <DropdownMenuContent align="end" className="w-48">
                  {/* Edit - selalu tampil jika punya akses */}
                  {canRead('users-list') && canUpdate('users-list') && (
                    <DropdownMenuItem onClick={() => onEdit(u)} className="cursor-pointer">
                      <Edit className="mr-2 h-4 w-4" />
                      Edit
                    </DropdownMenuItem>
                  )}
                  
                  {/* Setel Kata Sandi - tidak tampil jika: 1) user sendiri atau 2) target adalah admin dan user juga admin */}
                  {user?.id !== u.id && !(user?.role === 'admin' && u.role === 'admin') && canUpdate('users-list') && (
                    <DropdownMenuItem 
                      onClick={(e) => {
                        e.stopPropagation();
                        onSetPassword(u);
                      }} 
                      className="cursor-pointer"
                    >
                      <Key className="mr-2 h-4 w-4" />
                      Setel Kata Sandi
                    </DropdownMenuItem>
                  )}
                  
                  {/* Tautan Setel Ulang Sandi WhatsApp - tidak tampil untuk user sendiri */}
                  {user?.id !== u.id && canUpdate('users-list') && (
                    <DropdownMenuItem 
                      onClick={() => {
                        console.log('🔍 Reset Password clicked for user:', u);
                        console.log('🔍 User ID:', u.id);
                        console.log('🔍 User keys:', Object.keys(u));
                        onResetPassword(u);
                      }} 
                      className="cursor-pointer"
                    >
                      <Send className="mr-2 h-4 w-4" />
                      Tautan Setel Ulang Sandi
                    </DropdownMenuItem>
                  )}
                  
                  {/* Hapus - tidak tampil untuk user sendiri */}
                  {user?.id !== u.id && canDeletePerm('users-list') && (
                    <DropdownMenuItem
                      onClick={() => setDeleteTarget(u)}
                      className="cursor-pointer text-red-600 focus:text-red-600"
                    >
                      <Trash2 className="mr-2 h-4 w-4" />
                      <span>Hapus</span>
                    </DropdownMenuItem>
                  )}
                </DropdownMenuContent>
              </DropdownMenu>
            </TableCell>


          </TableRow>
        ))}
      </TableBody>
    </Table>

    {/* DELETE CONFIRMATION DIALOG */}
    <AlertDialog open={!!deleteTarget} onOpenChange={() => setDeleteTarget(null)}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>
            Hapus user {deleteTarget?.fullname}?
          </AlertDialogTitle>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Batal</AlertDialogCancel>
          <AlertDialogAction
            className="bg-red-600 hover:bg-red-700 text-white"
            onClick={handleDelete}
          >
            Hapus
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
    </>
  );
}
