import React, { useState, useEffect, useCallback } from 'react';
import { API_BASE_URL } from '@/config/api';
import { useAuth } from "@/contexts/AuthContext";
import { AlertDialog, AlertDialogContent, AlertDialogHeader, AlertDialogFooter, AlertDialogTitle, AlertDialogOverlay, AlertDialogCancel, AlertDialogAction, AlertDialogPortal } from "@/components/ui/alert-dialog";

const EMPTY_FORM  = { name:'', location:'', url:'', stream_type:'hls', use_proxy:0, width:1280, height:720, status:'active', group_id:'' };
const EMPTY_GROUP = { name:'', description:'' };

const STREAM_TYPES = [
  { value:'hls',  label:'HLS',  hint:'https://...stream.m3u8 ',   color:'#38bdf8' },
  { value:'rtsp', label:'RTSP', hint:'rtsp://user:pass@ip/stream',color:'#f59e0b' },
  { value:'rtmp', label:'RTMP', hint:'rtmp://ip/live/stream',     color:'#ef4444' },
];

async function fetchWithAuth(url, options = {}, token) {
  const res = await fetch(url, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...(token && { Authorization: `Bearer ${token}` }),
      ...(options.headers || {}),
    },
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err?.detail || `HTTP ${res.status}`);
  }

  return res.json().catch(() => ({}));
}

/* ── tiny helpers ── */
function safeArray(v) { return Array.isArray(v) ? v : []; }

function TypeBadge({ type }) {
  const c = { hls:'#38bdf8', rtsp:'#f59e0b', rtmp:'#ef4444' }[type] || '#888';
  return (
    <span style={{ fontSize:10,fontWeight:700,padding:'1px 6px',borderRadius:4,
      background:`${c}22`,color:c,fontFamily:'monospace',border:`1px solid ${c}44` }}>
      {(type||'hls').toUpperCase()}
    </span>
  );
}

function Toast({ toasts }) {
  return (
    <div className="toast-container">
      {toasts.map(t => (
        <div key={t.id} className={`toast ${t.type}`}>
          {t.type==='success'
            ? <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="var(--success)" strokeWidth="2.5"><polyline points="20 6 9 17 4 12"/></svg>
            : <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="var(--danger)" strokeWidth="2.5"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>}
          {t.msg}
        </div>
      ))}
    </div>
  );
}

/* ── Responsive hook ── */
function useResponsive() {
  const [isMobile, setIsMobile] = useState(false);
  const [isTablet, setIsTablet] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);

  useEffect(() => {
    const check = () => {
      const w = window.innerWidth;
      setIsMobile(w <= 768);
      setIsTablet(w > 768 && w <= 1024);
      if (w > 1024) setSidebarOpen(false);
    };
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  return { isMobile, isTablet, sidebarOpen, setSidebarOpen };
}

export default function CCTVConfig() {
  const [cctvList,       setCctvList]       = useState([]);
  const [groups,         setGroups]         = useState([]);
  const [stats,          setStats]          = useState({ total:0,active:0,inactive:0,total_groups:0 });
  const [loading,        setLoading]        = useState(true);
  const [activeTab,      setActiveTab]      = useState('cctv');
  const [showCctvModal,  setShowCctvModal]  = useState(false);
  const [showGroupModal, setShowGroupModal] = useState(false);
  const [editItem,       setEditItem]       = useState(null);
  const [editGroup,      setEditGroup]      = useState(null);
  const [form,           setForm]           = useState({ ...EMPTY_FORM });
  const [groupForm,      setGroupForm]      = useState({ ...EMPTY_GROUP });
  const [saving,         setSaving]         = useState(false);
  const [toasts,         setToasts]         = useState([]);
  const { token } = useAuth();
  const { isMobile, isTablet, sidebarOpen, setSidebarOpen } = useResponsive();

  const [openDelete, setOpenDelete] = useState(false);
  const [deleteType, setDeleteType] = useState(null);
  const [selectedItem, setSelectedItem] = useState(null);

  const toast = useCallback((msg, type='success') => {
    const id = Date.now();
    setToasts(t => [...t, { id, msg, type }]);
    setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 3000);
  }, []);

  const fetchAll = useCallback(async () => {
    setLoading(true);
    try {
      const [l, g, s] = await Promise.all([
        fetchWithAuth(`${API_BASE_URL}/api/cctv`, {}, token),
        fetchWithAuth(`${API_BASE_URL}/api/cctv/groups`, {}, token),
        fetchWithAuth(`${API_BASE_URL}/api/cctv/stats`, {}, token),
      ]);

      setCctvList(safeArray(l));
      setGroups(safeArray(g));
      setStats(s && typeof s === 'object' ? s : { total:0,active:0,inactive:0,total_groups:0 });
    } catch (e) {
      console.error('fetchAll error:', e);
      toast('Gagal memuat data','error');
    } finally {
      setLoading(false);
    }
  }, [token, toast]);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  /* ── CCTV ── */
  const openAdd  = () => { setEditItem(null); setForm({ ...EMPTY_FORM }); setShowCctvModal(true); };
  const openEdit = (item) => {
    setEditItem(item);
    setForm({
      name: item.name || '',
      location: item.location || '',
      url: item.url || '',
      stream_type: item.stream_type || 'hls',
      use_proxy: item.use_proxy ? 1 : 0,
      width: item.width || 1280,
      height: item.height || 720,
      status: item.status || 'active',
      group_id: item.group_id != null ? String(item.group_id) : '',
    });
    setShowCctvModal(true);
  };

  const saveCctv = async () => {
    if (!form.name.trim() || !form.url.trim() || !form.location.trim()) {
      toast('Nama, Lokasi, dan URL wajib diisi','error'); return;
    }
    setSaving(true);
    try {
      const endpoint = editItem ? `${API_BASE_URL}/api/cctv/${editItem.id}` : `${API_BASE_URL}/api/cctv`;
      const payload = {
        name: form.name,
        location: form.location,
        url: form.url,
        stream_type: form.stream_type,
        use_proxy: form.use_proxy ? 1 : 0,
        width: Number(form.width) || 1280,
        height: Number(form.height) || 720,
        status: form.status,
        group_id: form.group_id ? Number(form.group_id) : null,
      };
      await fetchWithAuth(endpoint, {
        method: editItem ? 'PUT' : 'POST',
        body: JSON.stringify(payload),
      }, token);

      toast(editItem ? 'CCTV diperbarui!' : 'CCTV ditambahkan!');
      setShowCctvModal(false);
      fetchAll();
    } catch (e) { toast(e.message || 'Gagal menyimpan','error'); }
    finally { setSaving(false); }
  };

  const deleteCctv = (item) => {
    setDeleteType('cctv');
    setSelectedItem(item);
    setOpenDelete(true);
  };

  const toggleStatus = async (item) => {
    const newStatus = item.status === 'active' ? 'inactive' : 'active';
    try {
      await fetchWithAuth(`${API_BASE_URL}/api/cctv/${item.id}`, {
        method: 'PUT',
        body: JSON.stringify({ status: newStatus }),
      }, token);
      fetchAll();
    } catch { toast('Gagal ubah status','error'); }
  };

  const confirmDelete = async () => {
    if (!selectedItem) return;
    try {
      if (deleteType === 'cctv') {
        await fetchWithAuth(`${API_BASE_URL}/api/cctv/${selectedItem.id}`, { method: 'DELETE' }, token);
        toast('CCTV dihapus');
      }
      if (deleteType === 'group') {
        await fetchWithAuth(`${API_BASE_URL}/api/cctv/groups/${selectedItem.id}`, { method: 'DELETE' }, token);
        toast('Group dihapus');
      }
      setOpenDelete(false);
      setSelectedItem(null);
      fetchAll();
    } catch (e) {
      toast(e.message || 'Gagal menghapus', 'error');
    }
  };

  /* ── Group ── */
  const openAddGroup  = () => { setEditGroup(null); setGroupForm({ ...EMPTY_GROUP }); setShowGroupModal(true); };
  const openEditGroup = (g) => { setEditGroup(g); setGroupForm({ name: g.name||'', description: g.description||'' }); setShowGroupModal(true); };

  const saveGroup = async () => {
    if (!groupForm.name.trim()) { toast('Nama group wajib diisi','error'); return; }
    setSaving(true);
    try {
      const endpoint = editGroup ? `${API_BASE_URL}/api/cctv/groups/${editGroup.id}` : `${API_BASE_URL}/api/cctv/groups`;
      await fetchWithAuth(endpoint, {
        method: editGroup ? 'PUT' : 'POST',
        body: JSON.stringify(groupForm),
      }, token);

      toast(editGroup ? 'Group diperbarui!' : 'Group ditambahkan!');
      setShowGroupModal(false);
      fetchAll();
    } catch (e) { toast(e.message || 'Gagal menyimpan','error'); }
    finally { setSaving(false); }
  };

  const deleteGroup = (g) => {
    setDeleteType('group');
    setSelectedItem(g);
    setOpenDelete(true);
  };

  /* ── Render ── */
  return (
    <div>
      {/* Stats */}
      <div className="stat-grid" style={{ 
        display: 'grid', 
        gridTemplateColumns: isMobile ? 'repeat(2, 1fr)' : 'repeat(auto-fit, minmax(160px, 1fr))',
        gap: '10px',
        marginBottom: '16px'
      }}>
        {[
          { icon:'📹', val:stats.total,        lbl:'Total CCTV',  cls:'blue'  },
          { icon:'✅', val:stats.active,       lbl:'Aktif',       cls:'green' },
          { icon:'❌', val:stats.inactive,     lbl:'Nonaktif',    cls:'red'   },
          { icon:'🏷', val:stats.total_groups, lbl:'Total Group', cls:'blue'  },
        ].map((s,i) => (
          <div key={i} className="stat-card" style={{ 
            padding: isMobile ? '12px' : '16px',
            minHeight: isMobile ? 'auto' : '80px'
          }}>
            <div className={`stat-icon ${s.cls}`} style={{ fontSize: isMobile ? 16 : 20 }}>{s.icon}</div>
            <div>
              <div className="stat-val" style={{ fontSize: isMobile ? '1.25rem' : '1.5rem' }}>{s.val}</div>
              <div className="stat-lbl" style={{ fontSize: isMobile ? 10 : 12 }}>{s.lbl}</div>
            </div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div style={{ display:'flex', gap:6, marginBottom:16, flexWrap:'wrap' }}>
        {[['cctv','📹 Daftar CCTV'],['groups','🏷 Kelola Group']].map(([t,l]) => (
          <button 
            key={t} 
            onClick={() => setActiveTab(t)}
            className={`btn ${activeTab===t?'btn-primary':'btn-ghost'}`}
            style={{ minHeight: 44, fontSize: isMobile ? 12 : 14 }}
          >{l}</button>
        ))}
      </div>

      {/* ═══ CCTV TAB ═══ */}
      {activeTab === 'cctv' && (
        <div className="card" style={{ overflowX: isMobile ? 'auto' : 'visible' }}>
          <div style={{ 
            display:'flex', 
            alignItems:'center', 
            justifyContent:'space-between', 
            marginBottom:16, 
            flexWrap:'wrap', 
            gap:8 
          }}>
            <div style={{ minWidth: 0, flex: 1 }}>
              <div style={{ fontSize: isMobile ? 14 : 16, fontWeight:700, color:'var(--text-primary)' }}>
                Daftar CCTV
              </div>
              <div style={{ fontSize: isMobile ? 10 : 12, color:'var(--text-muted)', marginTop:2 }}>
                Kelola kamera yang terdaftar
              </div>
            </div>
            <button 
              className="btn btn-primary" 
              onClick={openAdd}
              style={{ minHeight: 44, whiteSpace: 'nowrap' }}
            >+ Tambah CCTV</button>
          </div>

          {loading
            ? <div className="loading"><div className="spinner"/><span>Memuat…</span></div>
            : cctvList.length === 0
              ? <div className="empty-state">
                  <div className="empty-title">Belum ada CCTV terdaftar</div>
                  <div style={{fontSize:12}}>Klik "+ Tambah CCTV" untuk mulai</div>
                </div>
              : (
                <div className="table-wrap" style={{ 
                  overflowX: 'auto',
                  WebkitOverflowScrolling: 'touch'
                }}>
                  <table style={{ minWidth: isMobile ? '600px' : 'auto' }}>
                    <thead><tr>
                      <th>#</th><th>Nama CCTV</th><th>Lokasi</th><th>Group</th>
                      <th>Tipe</th><th>Proxy</th><th>URL Stream</th>
                      <th>Status</th><th>Dibuat</th><th>Aksi</th>
                    </tr></thead>
                    <tbody>
                      {cctvList.map((item, i) => (
                        <tr key={item.id}>
                          <td style={{ color:'var(--text-muted)', fontFamily:'monospace', fontSize:11 }}>{i+1}</td>
                          <td style={{ fontWeight:600, color:'var(--text-primary)', whiteSpace:'nowrap' }}>{item.name}</td>
                          <td style={{ fontSize:12, whiteSpace:'nowrap' }}>📍 {item.location}</td>
                          <td>
                            {item.group_name
                              ? <span style={{ fontSize:11, background:'var(--accent-dim)', color:'var(--accent)',
                                  border:'1px solid var(--border-accent)', borderRadius:6, padding:'2px 8px', whiteSpace:'nowrap' }}>
                                  {item.group_name}
                                </span>
                              : <span style={{ color:'var(--text-muted)', fontSize:11 }}>—</span>}
                          </td>
                          <td><TypeBadge type={item.stream_type}/></td>
                          <td>
                            {item.use_proxy
                              ? <span style={{ fontSize:10, fontWeight:700, color:'#f59e0b',
                                  background:'rgba(245,158,11,0.12)', border:'1px solid rgba(245,158,11,0.3)',
                                  borderRadius:4, padding:'1px 6px', whiteSpace:'nowrap' }}>✓ Proxy</span>
                              : <span style={{ fontSize:11, color:'var(--text-muted)' }}>—</span>}
                          </td>
                          <td style={{ maxWidth: isMobile ? 120 : 160 }}>
                            <span title={item.url} style={{ fontFamily:'monospace', fontSize:10,
                              background:'var(--bg-elevated)', padding:'2px 6px', borderRadius:4,
                              overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap',
                              display:'block', maxWidth: isMobile ? 120 : 160, color:'var(--accent)' }}>{item.url}</span>
                          </td>
                          <td>
                            <span 
                              className={`badge ${item.status}`} 
                              style={{ cursor:'pointer', whiteSpace:'nowrap', minHeight: 24, display: 'inline-flex', alignItems: 'center' }}
                              onClick={() => toggleStatus(item)} 
                              title="Klik untuk ubah status"
                            >
                              <span style={{ width:5,height:5,borderRadius:'50%',background:'currentColor',display:'inline-block',marginRight:4 }}/>
                              {item.status==='active' ? 'Aktif' : 'Nonaktif'}
                            </span>
                          </td>
                          <td style={{ fontSize:10, color:'var(--text-muted)', fontFamily:'monospace', whiteSpace:'nowrap' }}>
                            {new Date(item.created_at).toLocaleDateString('id-ID',{ day:'2-digit',month:'short',year:'numeric' })}
                          </td>
                          <td>
                            <div style={{ display:'flex', gap:4 }}>
                              <button 
                                className="btn btn-ghost btn-sm" 
                                onClick={() => openEdit(item)} 
                                title="Edit"
                                style={{ minHeight: 36, minWidth: 36 }}
                              >✏</button>
                              <button 
                                className="btn btn-danger btn-sm" 
                                onClick={() => deleteCctv(item)} 
                                title="Hapus"
                                style={{ minHeight: 36, minWidth: 36 }}
                              >🗑</button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )
          }
        </div>
      )}

      {/* ═══ GROUP TAB ═══ */}
      {activeTab === 'groups' && (
        <div className="card">
          <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:16, flexWrap:'wrap', gap:8 }}>
            <div>
              <div style={{ fontSize: isMobile ? 14 : 16, fontWeight:700, color:'var(--text-primary)' }}>Kelola Group CCTV</div>
              <div style={{ fontSize: isMobile ? 10 : 12, color:'var(--text-muted)', marginTop:2 }}>Buat dan atur nama group kamera</div>
            </div>
            <button 
              className="btn btn-primary" 
              onClick={openAddGroup}
              style={{ minHeight: 44 }}
            >+ Tambah Group</button>
          </div>
          {loading
            ? <div className="loading"><div className="spinner"/><span>Memuat…</span></div>
            : groups.length === 0
              ? <div className="empty-state"><div className="empty-title">Belum ada group</div><div style={{fontSize:12}}>Klik "+ Tambah Group" untuk mulai</div></div>
              : (
                <div style={{ 
                  display:'grid', 
                  gridTemplateColumns: isMobile ? '1fr' : 'repeat(auto-fill, minmax(220px, 1fr))', 
                  gap: isMobile ? 8 : 12 
                }}>
                  {groups.map(g => (
                    <div key={g.id} style={{ background:'var(--bg-elevated)', border:'1px solid var(--border)',
                      borderRadius:12, padding: isMobile ? 12 : 16, display:'flex', flexDirection:'column', gap:10 }}>
                      <div style={{ display:'flex', alignItems:'flex-start', justifyContent:'space-between', gap:8 }}>
                        <div style={{ minWidth:0 }}>
                          <div style={{ fontSize: isMobile ? 13 : 14, fontWeight:700, color:'var(--text-primary)', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>
                            🏷 {g.name}
                          </div>
                          <div style={{ fontSize:11, color:'var(--text-muted)', marginTop:3 }}>{g.description || '—'}</div>
                        </div>
                        <span style={{ fontSize: isMobile ? 16 : 20, fontWeight:800, color:'var(--accent)', flexShrink:0,
                          background:'var(--accent-dim)', border:'1px solid var(--border-accent)',
                          borderRadius:8, padding:'2px 10px', lineHeight:'1.8' }}>{g.cctv_count}</span>
                      </div>
                      <div style={{ fontSize:11, color:'var(--text-muted)' }}>{g.cctv_count} kamera terdaftar</div>
                      <div style={{ display:'flex', gap:6 }}>
                        <button 
                          className="btn btn-ghost btn-sm" 
                          style={{ flex:1, minHeight: 40 }} 
                          onClick={() => openEditGroup(g)}
                        >✏ Edit</button>
                        <button 
                          className="btn btn-danger btn-sm" 
                          onClick={() => deleteGroup(g)}
                          style={{ minHeight: 40, minWidth: 40 }}
                        >🗑</button>
                      </div>
                    </div>
                  ))}
                </div>
              )
          }
        </div>
      )}

      {/* ═══ MODAL CCTV ═══ */}
      {showCctvModal && (
        <div className="modal-overlay" onClick={e => e.target===e.currentTarget && setShowCctvModal(false)}>
          <div className="modal" style={{ 
            maxWidth: isMobile ? 'calc(100% - 16px)' : 520, 
            width: 'calc(100% - 32px)',
            margin: isMobile ? '8px auto' : 'auto',
            maxHeight: isMobile ? '95vh' : '90vh',
            overflowY: 'auto'
          }}>
            <div className="modal-header">
              <div className="modal-title">{editItem ? 'Edit CCTV' : 'Tambah CCTV Baru'}</div>
              <button className="modal-close" onClick={() => setShowCctvModal(false)} style={{ minHeight: 36, minWidth: 36 }}>×</button>
            </div>

            {/* Stream type */}
            <div className="form-group">
              <label className="form-label">Tipe Stream *</label>
              <div style={{ display:'flex', gap:6, flexWrap: 'wrap' }}>
                {STREAM_TYPES.map(t => (
                  <button key={t.value} type="button"
                    onClick={() => setForm(f => ({ ...f, stream_type:t.value, use_proxy:0 }))}
                    style={{ 
                      flex: isMobile ? '1 1 calc(33% - 4px)' : 1, 
                      padding:'10px 4px', 
                      borderRadius:8, 
                      cursor:'pointer',
                      fontSize:12, 
                      fontWeight:700, 
                      fontFamily:'Sora,sans-serif',
                      border:`1.5px solid ${form.stream_type===t.value ? t.color : 'var(--border)'}`,
                      background: form.stream_type===t.value ? `${t.color}18` : 'var(--bg-elevated)',
                      color: form.stream_type===t.value ? t.color : 'var(--text-muted)',
                      minHeight: 44
                    }}>
                    {t.label}
                  </button>
                ))}
              </div>
              <div style={{ fontSize:10, color:'var(--text-muted)', marginTop:4, fontFamily:'monospace' }}>
                Contoh: {STREAM_TYPES.find(t=>t.value===form.stream_type)?.hint}
              </div>
            </div>

            <div className="form-row" style={{ gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr' }}>
              <div className="form-group">
                <label className="form-label">Nama CCTV *</label>
                <input className="form-input" placeholder="cth: CCTV Gerbang Utama"
                  value={form.name} onChange={e => setForm(f => ({ ...f, name:e.target.value }))}
                  style={{ minHeight: 44 }}
                />
              </div>
              <div className="form-group">
                <label className="form-label">Lokasi *</label>
                <input className="form-input" placeholder="cth: Gerbang Depan"
                  value={form.location} onChange={e => setForm(f => ({ ...f, location:e.target.value }))}
                  style={{ minHeight: 44 }}
                />
              </div>
            </div>

            <div className="form-row" style={{ gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr' }}>
              <div className="form-group">
                <label className="form-label">Group</label>
                <select className="form-select"
                  value={form.group_id != null ? String(form.group_id) : ''}
                  onChange={e => setForm(f => ({ ...f, group_id: e.target.value || '' }))}
                  style={{ minHeight: 44 }}
                >
                  <option value="">— Tanpa Group —</option>
                  {safeArray(groups).map(g => (
                    <option key={g.id} value={String(g.id)}>{g.name}</option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label className="form-label">Status</label>
                <select className="form-select" value={form.status}
                  onChange={e => setForm(f => ({ ...f, status:e.target.value }))}
                  style={{ minHeight: 44 }}
                >
                  <option value="active">Aktif</option>
                  <option value="inactive">Nonaktif</option>
                </select>
              </div>
            </div>

            <div className="form-group">
              <label className="form-label">URL Stream *</label>
              <input className="form-input"
                placeholder={STREAM_TYPES.find(t=>t.value===form.stream_type)?.hint || ''}
                value={form.url}
                onChange={e => setForm(f => ({ ...f, url:e.target.value }))}
                style={{ minHeight: 44 }}
              />
            </div>

            {/* Proxy toggle — HLS only */}
            {form.stream_type === 'hls' && (
              <div className="form-group">
                <label style={{ display:'flex', alignItems:'flex-start', gap:10, cursor:'pointer' }}>
                  <div style={{ position:'relative', width:44, height:26, flexShrink:0, marginTop:1 }}>
                    <input type="checkbox" checked={!!form.use_proxy}
                      onChange={e => setForm(f => ({ ...f, use_proxy: e.target.checked ? 1 : 0 }))}
                      style={{ position:'absolute',opacity:0,width:'100%',height:'100%',cursor:'pointer',margin:0,zIndex:1 }}/>
                    <div style={{ width:44, height:26, borderRadius:13, transition:'background 0.2s',
                      background: form.use_proxy ? 'var(--accent)' : 'var(--bg-elevated)',
                      border:'1px solid var(--border)' }}/>
                    <div style={{ position:'absolute', top:3, left: form.use_proxy ? 21 : 3,
                      width:20, height:20, borderRadius:'50%', background:'#fff',
                      transition:'left 0.2s', boxShadow:'0 1px 3px rgba(0,0,0,0.3)', pointerEvents:'none' }}/>
                  </div>
                  <div>
                    <div style={{ fontSize:13, fontWeight:600, color:'var(--text-primary)' }}>
                      Gunakan HLS Proxy {form.use_proxy ? <span style={{ color:'#f59e0b', fontSize:11 }}>● Aktif</span> : ''}
                    </div>
                    <div style={{ fontSize:11, color:'var(--text-muted)', marginTop:2, lineHeight:1.5 }}>
                      Aktifkan jika stream error CORS (contoh: URL dari instansi pemerintah/dishub).
                    </div>
                  </div>
                </label>
              </div>
            )}

            {form.stream_type === 'rtsp' && (
              <div style={{ fontSize:11, color:'var(--warning)', padding:'8px 12px',
                background:'rgba(251,191,36,0.08)', border:'1px solid rgba(251,191,36,0.25)',
                borderRadius:8, lineHeight:1.6, marginBottom:12 }}>
                ⚠ RTSP memerlukan <strong>ffmpeg</strong> terinstall di server backend.
              </div>
            )}

            <div className="form-row" style={{ gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr' }}>
              <div className="form-group">
                <label className="form-label">Lebar (px)</label>
                <input className="form-input" type="number" min="320" max="3840"
                  value={form.width} onChange={e => setForm(f => ({ ...f, width:e.target.value }))}
                  style={{ minHeight: 44 }}
                />
              </div>
              <div className="form-group">
                <label className="form-label">Tinggi (px)</label>
                <input className="form-input" type="number" min="240" max="2160"
                  value={form.height} onChange={e => setForm(f => ({ ...f, height:e.target.value }))}
                  style={{ minHeight: 44 }}
                />
              </div>
            </div>

            <div className="modal-footer" style={{ flexWrap: 'wrap', gap: 8 }}>
              <button className="btn btn-ghost" type="button" onClick={() => setShowCctvModal(false)} style={{ minHeight: 44 }}>
                Batal
              </button>
              <button className="btn btn-primary" type="button" onClick={saveCctv} disabled={saving} style={{ minHeight: 44 }}>
                {saving ? 'Menyimpan…' : editItem ? 'Simpan Perubahan' : 'Tambah CCTV'}
              </button>
            </div>
          </div>
        </div>
        
      )}
       <AlertDialog open={openDelete} onOpenChange={setOpenDelete}>
        <AlertDialogPortal container={document.body}>
          
          <AlertDialogOverlay className="fixed inset-0 bg-black/60 z-[99998]" />

          <AlertDialogContent className="fixed z-[99999] max-w-md">
            <AlertDialogHeader>
              <AlertDialogTitle>
                {deleteType === 'cctv' && `Hapus CCTV "${selectedItem?.name}"?`}
                {deleteType === 'group' && `Hapus group "${selectedItem?.name}"?`}
              </AlertDialogTitle>

              {deleteType === 'group' && (
                <p className="text-sm text-gray-500">
                  CCTV di dalamnya akan menjadi tanpa group.
                </p>
              )}
            </AlertDialogHeader>

            <AlertDialogFooter>
              <AlertDialogCancel>Batal</AlertDialogCancel>

              <AlertDialogAction
                className="bg-red-600 hover:bg-red-700 text-white"
                onClick={confirmDelete}
              >
                Hapus
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>

        </AlertDialogPortal>
      </AlertDialog>

     
      {/* ═══ MODAL GROUP ═══ */}
      {showGroupModal && (
        <div className="modal-overlay" onClick={e => e.target===e.currentTarget && setShowGroupModal(false)}>
          <div className="modal" style={{ 
            maxWidth: isMobile ? 'calc(100% - 16px)' : 400, 
            width: 'calc(100% - 32px)',
            margin: isMobile ? '8px auto' : 'auto'
          }}>
            <div className="modal-header">
              <div className="modal-title">{editGroup ? 'Edit Group' : 'Tambah Group Baru'}</div>
              <button className="modal-close" onClick={() => setShowGroupModal(false)} style={{ minHeight: 36, minWidth: 36 }}>×</button>
            </div>
            <div className="form-group">
              <label className="form-label">Nama Group *</label>
              <input className="form-input" placeholder="cth: Area Perumahan"
                value={groupForm.name}
                onChange={e => setGroupForm(f => ({ ...f, name:e.target.value }))}
                style={{ minHeight: 44 }}
              />
            </div>
            <div className="form-group">
              <label className="form-label">Deskripsi</label>
              <input className="form-input" placeholder="Keterangan singkat (opsional)"
                value={groupForm.description}
                onChange={e => setGroupForm(f => ({ ...f, description:e.target.value }))}
                style={{ minHeight: 44 }}
              />
            </div>
            <div className="modal-footer" style={{ flexWrap: 'wrap', gap: 8 }}>
              <button className="btn btn-ghost" type="button" onClick={() => setShowGroupModal(false)} style={{ minHeight: 44 }}>
                Batal
              </button>
              <button className="btn btn-primary" type="button" onClick={saveGroup} disabled={saving} style={{ minHeight: 44 }}>
                {saving ? 'Menyimpan…' : editGroup ? 'Simpan' : 'Buat Group'}
              </button>
            </div>
          </div>
        </div>
      )}

      <Toast toasts={toasts}/>
    </div>
  );
}
